import json,re
from pathlib import Path
B=Path('benchmarks/dense500')
DOMAINS='case_context demographics conditions symptoms_function medications allergies procedures_devices observations oncology family_genetics reproductive_perinatal social_exposures outcomes care_plans'.split()
class Builder:
 def __init__(self,article):
  self.a=json.loads((B/'sources'/f'{article}.json').read_text()); self.s={s['segment_id']:s for s in self.a['segments']}; self.p=[]; self.cover={};self.fig=[];self.limits=['Figure pixels were not inspected; visual details are restricted to captions.']
 def evidence(self,seg,quote=None):
  q=self.s[seg]['text'] if quote is None else quote
  assert q in self.s[seg]['text'],(seg,q)
  return [{'segment_id':seg,'quote':q}]
 def patient(self,label,seg,species='human',quote=None):
  p={'patient_id':f'p{len(self.p)+1}','label':label,'species':species,'species_as_documented':'cat' if species=='nonhuman' else 'human patient','identity_evidence':self.evidence(seg,quote),'facts':[],'events':[],'temporal_relations':[],'summary':[],'domain_coverage':{},'ambiguities':[]};self.p.append(p);self.cur=p;return p
 def fact(self,task,seg,statement,fields,quote=None,certainty='supported',notes='',extra_ev=None):
  notes=notes or fields.pop('notes','')
  pid=self.cur['patient_id']; fid=f'{pid}-f{len(self.cur["facts"])+1:03}'
  f={'fact_id':fid,'task':task,'collection':None if task=='case_context' else 'items','fields':fields,'evidence':self.evidence(seg,quote)+(extra_ev or []),'clinical_statement':statement,'certainty':certainty,'scoring':'include' if certainty=='supported' else 'review_only','notes':notes}
  if task!='case_context':f['fields']={'subject':'index_patient','assertion':'present',**fields}
  self.cur['facts'].append(f);self.cover.setdefault(seg,set()).add(pid);return fid
 def obs(self,seg,name,value=None,quote=None,kind='laboratory',**kw):
  return self.fact('observations',seg,f'{name}: {value if value is not None else kw.get("text_value",kw.get("flag","documented"))}',{'name':name,'kind':kind,'status':'resulted',**({'numeric_value':value} if value is not None else {}),**kw},quote)
 def cond(self,seg,name,quote=None,**kw):return self.fact('conditions',seg,name,{'name':name,'verification_status':'confirmed',**kw},quote)
 def symptom(self,seg,name,quote=None,**kw):return self.fact('symptoms_function',seg,name,{'name':name,'kind':'symptom',**kw},quote)
 def proc(self,seg,name,quote=None,**kw):return self.fact('procedures_devices',seg,name,{'name':name,'kind':'procedure','action':'completed',**kw},quote)
 def med(self,seg,name,quote=None,**kw):return self.fact('medications',seg,name,{'name':name,'action':'administered',**kw},quote)
 def event(self,desc,facts,seg,time=None,occurrence='occurred',quote=None):
  eid=f'{self.cur["patient_id"]}-e{len(self.cur["events"])+1:02}';self.cur['events'].append({'event_id':eid,'description':desc,'occurrence':occurrence,'fact_ids':facts,'time_text':time,'evidence':self.evidence(seg,quote)});return eid
 def relation(self,a,b,seg,relation='before',quote=None):self.cur['temporal_relations'].append({'from_event_id':a,'to_event_id':b,'relation':relation,'evidence':self.evidence(seg,quote)})
 def summary(self,text,ids):self.cur['summary'].append({'text':text,'fact_ids':ids})
 def figure(self,fid,seg,panels,scope='individual',pids=None,notes=''):
  if pids is None:pids=[self.cur['patient_id']]
  self.fig.append({'figure_id':fid,'caption_evidence':self.evidence(seg),'patient_ids':pids,'scope':scope,'panels':[{'panel':label,'patient_ids':ids,'scope':sc,'description_from_caption':desc,'modality':mod,'body_part':body,'evidence':self.evidence(seg,q)} for label,ids,sc,desc,mod,body,q in panels],'caption_summary':self.s[seg]['text'],'visual_status':'not_inspected','visual_description':None,'attribution_notes':notes})
 def save(self,background=(),aggregate=(),patient_segments=()):
  for p in self.p:
   tasks={f['task'] for f in p['facts']};p['domain_coverage']={d:{'status':'documented' if d in tasks else 'not_documented','note':'Source-grounded facts retained.' if d in tasks else 'No patient-specific documentation in retained source.'} for d in DOMAINS}
  rows=[]
  for sid,s in self.s.items():
   ids=sorted(self.cover.get(sid,set()))
   if s['kind']=='figure_caption':disp='figure_caption';ids=sorted({pid for f in self.fig if any(e['segment_id']==sid for e in f['caption_evidence']) for pid in f['patient_ids']}); note='Caption and panel attribution reviewed; pixels not inspected.'
   elif sid in aggregate:disp='aggregate';note='Literature/cohort material; not an index-patient fact.'
   elif sid in background:disp='background';note='Background, methods without additional clinical findings, or article administration.'
   elif ids or sid in patient_segments:disp='patient_facts';note='Reviewed for index-patient clinical content.';ids=ids or [p['patient_id'] for p in self.p]
   else:disp='background';note='Reviewed; no additional individual patient facts.'
   rows.append({'segment_id':sid,'disposition':disp,'patient_ids':ids,'note':note})
  out={'schema_version':'dense-article-annotation/1','article_id':self.a['article_id'],'text_sha256':self.a['text_sha256'],'xml_sha256':self.a['xml_sha256'],'disposition':'individual_cases' if self.p else 'aggregate_only','patients':self.p,'figures':self.fig,'source_coverage':rows,'article_limitations':self.limits,'annotation_provenance':{'annotator_model':'GPT-6.1 Sol','passes':['Complete original source JSON and text review; patient enumeration and segment ownership','Clinical extraction including negative findings and normal table rows','Repeat patient text/table/caption review for omission, attribution and polarity','Chronology, quantities, units and panel ownership review','Local validation of every exact quote and fact/event reference'],'prior_predictions_consulted':False,'status':'draft'}}
  def check(obj):
   if isinstance(obj,dict):
    if 'segment_id' in obj and 'quote' in obj:assert obj['quote'] in self.s[obj['segment_id']]['text'],obj
    for v in obj.values():check(v)
   elif isinstance(obj,list):
    for x in obj:check(x)
  check(out);(B/'drafts'/f'{self.a["article_id"]}.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(self.a['article_id'],[len(p['facts']) for p in self.p])

