 b=Builder('PMC12784445.1');p=b.patient('79-year-old woman with Takotsubo cardiomyopathy and progressive AV block','b00006',quote='A 79-year-old woman with a background of poorly controlled hypertension presented with severe central crushing chest pain at rest.')
 ctx=b.fact('case_context','b00006','Emergency presentation with crushing chest pain during emotional stress',{'case_kind':'clinical_case','species':'human','index_subject_description':p['label'],'care_setting':'emergency department','chief_complaint':'severe central crushing chest pain at rest'},quote='A 79-year-old woman with a background of poorly controlled hypertension presented with severe central crushing chest pain at rest.')
 age=b.fact('demographics','b00006','79 years old',{'attribute':'age_at_presentation','numeric_value':79,'unit':'years'},quote='79-year-old');sex=b.fact('demographics','b00006','Woman',{'attribute':'documented_sex','text_value':'woman'},quote='woman')
 ht=b.cond('b00006','Hypertension',role='comorbidity',severity='poorly controlled',quote='a background of poorly controlled hypertension')
