 ppci=b.proc('b00006','Emergency primary percutaneous coronary intervention intention',action='planned',quote='She was taken to the cardiac catheterisation laboratory as an emergency case for primary percutaneous coronary intervention (PPCI).',notes='Transfer/intention for PPCI is documented; actual PCI/stent deployment is not stated.')
