 ef=b.obs('b00007','Initial echo LVEF',35,unit='%',text_value='~35%',quote='a left ventricular ejection fraction (LVEF) of ~35%',notes='Approximate value explicitly retained as ~35%; comparator enum cannot express approximation.') if False else b.fact('observations','b00007','Initial echo LVEF approximately 35%',{'name':'Initial echo LVEF','kind':'imaging','status':'resulted','numeric_value':35,'unit':'%','text_value':'~35%'},quote='a left ventricular ejection fraction (LVEF) of ~35%',notes='Approximate value preserved verbatim; do not treat as exact 35%.')
 for name,q in [('LV systolic function','severe left ventricular systolic dysfunction'),('LV size','a moderately dilated left ventricle'),('LV diastolic function','impaired diastolic function'),('LA size','Her left atrium was also severely dilated')]:b.obs('b00007',name,kind='imaging',text_value=q,quote=q)
