 for name in ['T1','T2']:b.obs('b00008','MRI '+name,kind='imaging',flag='high',text_value='elevated in midventricular and apical myocardium, near transmural oedema and inflammation',quote='T1 and T2 levels were elevated in midventricular and apical myocardium in keeping with near transmural oedema and inflammation (Figure 4).')
