 deviceplan=b.fact('care_plans','b00009','Device multidisciplinary team recommended CRT-P because of AV block, trifascicular disease and poor LVEF',{'action_text':'implant CRT-P','plan_type':'other','target':'high-grade AV block with poor LVEF and preexisting trifascicular block','action_status':'recommended'},quote='Due to the persistent high-grade AV block, discussions were held in the device multidisciplinary team meeting, and the consensus was that, due to the high-grade AV block [], pre-existing trifascicular block and poor LVEF, she would benefit from a CRT-P')
