 b.fact('care_plans','b00016','CRT-P selected to reduce pacing-related heart-failure risk',{'action_text':'maintain ventricular synchrony and reduce pacing-related heart failure risk using CRT-P','plan_type':'other','action_status':'completed'},quote='This option was chosen to maintain ventricular synchrony and reduce the risk of pacing-related heart failure.',notes='Records rationale/decision, not proof of actual long-term pacing dependence or prevented heart failure.')
 e1=b.event('Emergency chest-pain presentation and initial evaluation',[ctx,pain,working,t1,t2,trif],'b00006');e2=b.event('Coronary angiography and ventriculography with unobstructed coronaries/TTC pattern',[angio,angioresult,vent],'b00006');e3=b.event('MRI 48 hours after admission',[mri,dx],'b00008','48 hours post admission');e4=b.event('2:1 block observed after MRI',[av2,mob],'b00008',quote='After her MRI, she was noted to be in a 2:1 AV block (Figure 5).');e5=b.event('Repeat echo unchanged and high-grade AV block',[repeat,avhigh],'b00008','Four days later');e6=b.event('CRT-P recommended',[deviceplan],'b00009');e7=b.event('CRT-P implantation',[implant],'b00009','two days later');e8=b.event('Later postoperative findings, renal improvement and discharge',[hematoma,renal,recovery,discharge],'b00009','several days later');b.relation(e1,e2,'b00006');b.relation(e1,e3,'b00008');b.relation(e3,e4,'b00008');b.relation(e4,e5,'b00008');b.relation(e5,e6,'b00009');b.relation(e6,e7,'b00009');b.relation(e7,e8,'b00009')
