def vericiguat_case():
 b=Builder('PMC12813956.1');p=b.patient('78-year-old man with progressive HFrEF and CKD','b00008',quote='A 78-year-old man was evaluated in October 2021 for atrial flutter after reporting chest discomfort the previous week.')
 def tm(text):return {'text':text}
 ctx=b.fact('case_context','b00008','Initial atrial-flutter evaluation after prior-week chest discomfort',{'case_kind':'clinical_case','species':'human','index_subject_description':p['label'],'chief_complaint':'atrial flutter after chest discomfort'},quote='A 78-year-old man was evaluated in October 2021 for atrial flutter after reporting chest discomfort the previous week.')
 age=b.fact('demographics','b00008','Age 78 at presentation',{'attribute':'age_at_presentation','numeric_value':78,'unit':'years'},quote='78-year-old');sex=b.fact('demographics','b00008','Man',{'attribute':'documented_sex','text_value':'man'},quote='man')
 chest=b.symptom('b00008','Chest discomfort',time=tm('the previous week'),quote='after reporting chest discomfort the previous week.')
 cognitive=b.symptom('b00008','Cognitive impairment',kind='mental_status',assertion='absent',quote='He had no cognitive impairment')
 frail=b.symptom('b00008','Frailty',kind='functional_status',quote='was noted to be frail');capacity=b.symptom('b00008','Reduced functional capacity for strenuous tasks',kind='functional_status',activity_context='strenuous tasks',quote='with reduced functional capacity for strenuous tasks.')
 history=[]
 for n in ['hypertension','hyperlipidemia','gastroesophageal reflux disease','benign prostatic hyperplasia']:history.append(b.cond('b00008',n,role='history',quote='His medical history included hypertension, hyperlipidemia, gastroesophageal reflux disease, and benign prostatic hyperplasia.'))
 home=[]
 for n,d in [('tamsulosin',None),('triamterene/hydrochlorothiazide','37.5/25 mg'),('donepezil','10 mg'),('amlodipine','10 mg'),('atorvastatin','20 mg'),('pantoprazole','40 mg')]:
  kw={'action':'historical','time':tm('October 2021')}
  if d:kw.update(dose_text=d)
  if d and '/' not in d:kw.update(dose_value=float(d.split()[0]),dose_unit='mg')
  home.append(b.med('b00008',n,quote='Home medications included tamsulosin, triamterene/hydrochlorothiazide (37.5/25 mg), donepezil (10 mg), amlodipine (10 mg), atorvastatin (20 mg), and pantoprazole (40 mg).',**kw))
 flutter=b.cond('b00009','Atrial flutter',diagnostic_basis='ECG',time=tm('October 2021'),quote='Initial assessment revealed atrial flutter with a ventricular rate of 85 beats per minute and frequent premature ventricular complexes (PVCs) on electrocardiography (ECG) (Figure 1, ECG in October 2021).')
