 ap1=b.med('b00009','apixaban',action='started',dose_value=5,dose_unit='mg',dose_text='5 mg twice daily',frequency='twice daily',quote='He was started on apixaban 5 mg twice daily and metoprolol 25 mg twice daily.')
 met=b.med('b00009','metoprolol',action='started',dose_value=25,dose_unit='mg',dose_text='25 mg twice daily',frequency='twice daily',quote='He was started on apixaban 5 mg twice daily and metoprolol 25 mg twice daily.')
 choice=b.fact('care_plans','b00009','Patient elected medical management after detailed discussion',{'action_text':'medical management of rhythm abnormality','plan_type':'counseling','action_status':'completed','target':'rhythm abnormality'},quote='After a detailed discussion with the patient, he elected the medical management of his rhythm abnormality.',notes='Completed choice/discussion, not proof of any unreported treatment.')
 evalplan=b.fact('care_plans','b00009','Further evaluation planned',{'action_text':'further evaluation','plan_type':'follow_up','action_status':'planned'},quote='Further evaluation was planned; however, he traveled abroad and was subsequently lost to follow-up.')
 travel=b.fact('social_exposures','b00009','Traveled abroad before loss to follow-up',{'domain':'other','name':'travel abroad'},quote='he traveled abroad and was subsequently lost to follow-up.')
 lost=b.fact('outcomes','b00009','Subsequently lost to follow-up',{'event':'lost_to_follow_up','text_value':'lost to follow-up after travel abroad'},quote='he traveled abroad and was subsequently lost to follow-up.')
 readmit=b.fact('outcomes','b00010','Multiple admissions for decompensated HF before March 2022 return',{'event':'readmission','text_value':'multiple admissions for decompensated heart failure','time':tm('March 2022')},quote='He re-presented in March 2022 after multiple admissions for decompensated heart failure.')
 revised=[]
 for n,d,fr in [('sacubitril/valsartan','49/51 mg','twice daily'),('furosemide','20 mg','daily'),('rivaroxaban','20 mg','daily'),('spironolactone','25 mg','daily')]:
  kw={'action':'started','dose_text':d+' '+fr,'frequency':fr,'time':tm('March 2022'),'notes':'Medication revision in home country; precise initiation date unstated.'}
  if '/' not in d:kw.update(dose_value=float(d.split()[0]),dose_unit='mg')
