  a=b.fact('demographics',start,f'{age} years old',{'attribute':'age_at_presentation','numeric_value':age,'unit':'years'},quote=f'{age}-year-old');sx=b.fact('demographics',start,'Woman',{'attribute':'documented_sex','text_value':'woman'},quote='woman')
