  progress=b.fact('outcomes','b00009' if i==1 else 'b00010','Progressive symptoms for 15 months' if i==1 else 'Progressive symptoms over past year',{'event':'deterioration','text_value':'progressively worsening symptoms','follow_up_duration_text':'15 months' if i==1 else 'past year'},quote='The aforementioned symptoms had worsened progressively over the preceding 15 months' if i==1 else 'The patient reported similarly progressive symptoms for the past year.')
  prior=[]
