  exam=b.obs('b00014','Abdominal examination',kind='other',flag='normal',text_value='benign; non-contributory',quote='Non-contributory in both cases. Abdominal examination was benign with no signs of peritonitis or palpable masses.')
  periton=b.symptom('b00014','Signs of peritonitis',kind='sign',assertion='absent',quote='no signs of peritonitis or palpable masses');mass=b.symptom('b00014','Palpable abdominal masses',kind='sign',assertion='absent',quote='no signs of peritonitis or palpable masses')
  if i==1:
   cal=b.obs('b00015','Fecal calprotectin',250,unit='mg/kg',flag='high',text_value='mildly elevated',quote='Fecal calprotectin mildly elevated (250 mg/kg).');other=b.obs('b00015','Other laboratories',flag='normal',text_value='other labs within normal range',quote='Other labs within normal range.')
  else:other=b.obs('b00016','Laboratory tests',flag='normal',text_value='unremarkable laboratory tests',quote='Laboratory tests were unremarkable.')
