  oversight=b.fact('outcomes',sid,'Original CT interpretation did not mention vascular calcifications',{'event':'other','text_value':'SMA/celiac origin calcifications omitted from original radiology report'},quote='which had not been reported in the original radiology interpretation.' if i==1 else 'not mentioned in the radiology report (Figure 2A and B).')
