  ostium=b.obs(sid,'SMA ostial calcification on axial view',kind='imaging',text_value='extensive calcification at ostium',quote='Figure 1D shows extensive calcification at the SMA ostium when viewed in axial view.' if i==1 else 'Panel D shows extensive calcification at the SMA ostium when viewed in axial view.')
