def pediatric_thromboses():
 b=Builder('PMC12134816.1')
 def onc(seg,statement,fields,collection='tumors',quote=None):
  f=b.fact('oncology',seg,statement,fields,quote);b.cur['facts'][-1]['collection']=collection;return f
 def outcome(seg,text,event='improvement',quote=None,**kw):return b.fact('outcomes',seg,text,{'event':event,'text_value':text,**kw},quote)
 def clot(seg,name,quote=None,**kw):return b.cond(seg,name,role='complication',quote=quote,**kw)
 def labs(sids):
  out=[]
  for sid in sids:
   last=b.s[sid]['text'].split('\n')[-1];parts=last.split(' | ')
   if len(parts)!=3:continue
   n,ref,val=parts
   if val=='-':
    out.append(b.obs(sid,n,status='unknown',result_absent_reason='not_reported',reference_range_text=ref,notes='Dash denotes an unreported result, not a negative test.'));continue
   unit=next((u for u in ['× 10³/µL','× 10⁶/µL','g/dL','mg/dL','μg/mL','seconds','sec','%'] if u in ref),None)
   out.append(b.obs(sid,n,float(val),**({'unit':unit} if unit else {}),reference_range_text=ref,notes='Scaled unit retained from reference column; magnitude not converted.' if unit and '×' in unit else ''))
  return out
 def init(n,age,sex,sid,name,table):
  p=b.patient(f'Case {n}: {age}-year-old {sex} with {name}',sid)
  c=b.fact('case_context',sid,'Pediatric malignancy with venous thrombosis',{'case_kind':'clinical_case','species':'human','multiple_index_patients':True,'index_subject_description':p['label']})
  a=b.fact('demographics',sid,f'{age} years old',{'attribute':'age_at_presentation','numeric_value':age,'unit':'years'})
  sx=b.fact('demographics',sid,sex,{'attribute':'documented_sex','text_value':sex})
  tumor=onc(table,name,{'tumor_ref':'t1','name':name,'disease_extent':'hematologic'})
  return p,[c,a,sx,tumor]
 # CASE 1
 p,ids=init(1,6,'boy','b00007','B-cell precursor acute lymphoblastic leukemia','b00097')
 risklabel=b.obs('b00008','BCP-ALL risk classification',kind='other',text_value='high risk',quote='ALL B-12 protocol (high risk)')
 risk=onc('b00008','BCP-ALL treated on ALL B-12',{'tumor_ref':'t1','name':'BCP-ALL','disease_extent':'hematologic'},quote='BCP-ALL and was treated using the ALL B-12 protocol (high risk)')
 protocol=onc('b00008','ALL B-12 protocol treatment',{'tumor_ref':'t1','name':'ALL B-12 protocol (high risk)','modality':'systemic','action':'given'},'treatments',quote='was treated using the ALL B-12 protocol (high risk)')
 transf=b.proc('b00008','Platelet transfusion',quote='following a platelet transfusion')
 sat=b.obs('b00008','Initial SpO2',80,kind='vital',unit='%',text_value='80% on room air',time={'text':'Seven months after the initiation of treatment'},quote='Seven months after the initiation of treatment, during the first remission induction therapy, a drop in oxygen saturation (SpO₂ 80% on room air) was observed following a platelet transfusion, prompting further evaluation.')
 transfreact=b.cond('b00008','Desaturation related to platelet transfusion initially suspected',verification_status='provisional',assertion='possible',role='differential',quote='Although the desaturation was initially suspected to be related to the platelet transfusion, the episode lacked clinical features typically associated with a transfusion reaction.')
 nofeatures=b.obs('b00008','Clinical features of transfusion reaction',kind='other',flag='negative',text_value='episode lacked typical reaction features',quote='the episode lacked clinical features typically associated with a transfusion reaction.')
 l1=labs([f'b{x:05}' for x in [11,12,13,14,15,17,18,19,20,21,22,23,24]])
 pc=b.obs('b00008','Protein C interpretation',flag='normal',text_value='normal',quote='normal protein C and protein S levels');ps=b.obs('b00008','Protein S interpretation',flag='normal',text_value='normal',quote='normal protein C and protein S levels')
 neg1=b.obs('b00025','Immediate contrast CT lower limbs to lungs',kind='imaging',flag='negative',text_value='no gross thrombus',quote='A contrast-enhanced CT scan from the lower extremities to the lungs, conducted immediately after the onset of decreased oxygenation, revealed no evidence of a gross thrombus.')
 vq1=b.obs('b00025','First pulmonary V/Q scintigraphy',kind='imaging',text_value='reduced accumulation in S9 branch right lung base',time={'text':'nine days later','relation':'after','anchor':'initial CT/desaturation'},quote='a pulmonary ventilation-perfusion scintigraphy performed nine days later showed reduced accumulation in the S9 branch of the right lung base (Figure 1A)')
 pte=b.cond('b00025','Pulmonary thromboembolism',role='primary_diagnosis',diagnostic_basis='V/Q scintigraphy',quote='leading to a diagnosis of PTE.')
 approx=b.obs('b00025','Intermittent later SpO2 drops',90,kind='vital',unit='%',text_value='approximately 90%; occasional transient drops',quote='occasional transient drops in peripheral oxygen saturation to approximately 90%')
 negatives=[]
 for n in ['chest pain','dyspnea']:negatives.append(b.symptom('b00025',n,assertion='absent',quote='no reported chest pain or dyspnea.'))
 asym=b.symptom('b00025','Otherwise asymptomatic presentation',kind='functional_status',text_value='asymptomatic aside from occasional transient desaturation',quote='The patient remained asymptomatic, aside from occasional transient drops in peripheral oxygen saturation to approximately 90%, with no reported chest pain or dyspnea.')
 lm=b.med('b00026','low-molecular-weight heparin',indication='PTE/high-risk L-asparaginase phase',quote='low-molecular-weight heparin was administered during the high-risk period for thrombosis associated with L-asparaginase (L-Asp) therapy in the second re-induction phase.')
 lasp=b.med('b00026','L-asparaginase (L-Asp)',quote='L-asparaginase (L-Asp) therapy in the second re-induction phase.')
 noO2=b.symptom('b00026','Further oxygen saturation decreases during second re-induction',assertion='absent',quote='without further decreases in oxygen saturation or new signs of thrombosis.')
 noSigns=b.obs('b00026','New thrombosis signs during second re-induction',kind='other',flag='negative',text_value='no new signs of thrombosis',quote='without further decreases in oxygen saturation or new signs of thrombosis.')
 stable=outcome('b00026','No further oxygen saturation decreases or new thrombosis signs during second re-induction','follow_up',quote='The patient progressed without further decreases in oxygen saturation or new signs of thrombosis.')
 recur=b.symptom('b00027','Nocturnal oxygen desaturation during third re-induction',time={'text':'seven months after the initial PTE','relation':'after','anchor':'initial PTE'},quote='During the third re-induction therapy - seven months after the initial PTE - the patient experienced another episode of nocturnal oxygen desaturation.')
 neg2=b.obs('b00027','Repeat contrast CT lower limbs to lungs',kind='imaging',flag='negative',text_value='no thrombus',quote='Repeat contrast-enhanced CT scans from the lower extremities to the lungs again showed no thrombus.')
 vq2=b.obs('b00027','Repeat V/Q scintigraphy',kind='imaging',text_value='reduced flow in wedge-shaped areas of both lung fields',quote='pulmonary ventilation-perfusion scintigraphy revealed reduced pulmonary blood flow in wedge-shaped areas in both lung fields')
 exacerb=clot('b00027','PTE exacerbation',clinical_status='recurrence',quote='indicating exacerbation of PTE')
 dd2=b.obs('b00027','Second-event D-dimer',.9,unit='μg/mL',quote='D-dimer level of 0.9 μg/mL');at2=b.obs('b00027','Second-event AT3',115.9,unit='%',quote='AT3 of 115.9%')
 uf=b.med('b00027','unfractionated heparin',action='started',quote='anticoagulation was switched from low-molecular-weight heparin to unfractionated heparin');lmstop=b.med('b00027','low-molecular-weight heparin',action='stopped',quote='anticoagulation was switched from low-molecular-weight heparin to unfractionated heparin')
 monitoring=b.fact('care_plans','b00027','Coagulation parameters closely monitored',{'action_text':'closely monitor coagulation parameters','plan_type':'monitoring','action_status':'completed'},quote='coagulation parameters were closely monitored.')
 clear1=b.obs('b00028','Follow-up V/Q after UFH',kind='imaging',text_value='thrombus resolution',time={'text':'Approximately two months after initiating unfractionated heparin'},quote='Approximately two months after initiating unfractionated heparin for the second thrombotic episode, follow-up pulmonary ventilation-perfusion scintigraphy confirmed thrombus resolution.')
