 presentation=b.event('Emergency presentation after 48 hours of worsening dyspnea with pain, respiratory distress and initial examination',[ctx,dy,low,ap,ha,af,resp,conscious,orient,*vit],'b00008',time='over 48 hours');b.relation(hist,presentation,'b00008');b.relation(epre,presentation,'b00008');b.relation(edvt,presentation,'b00008')
