 b=Builder('PMC12661979.1')
 def out(sid,event,txt,q=None,**kw):return b.fact('outcomes',sid,txt,{'event':event,'text_value':txt,**kw},quote=q)
 def nutrition(sid,txt,q):return b.proc(sid,txt,kind='nonpharmacologic_therapy',quote=q)
 def common(i,age,sex,age_surg,sid,table):
  p=b.patient(f'Patient {i}: current age {age} years, {sex}, after transverse colon esophageal replacement',table,quote=f'Patient {i} (P{i}) | {age} | {sex}')
  ctx=b.fact('case_context',sid,'Post-colon-interposition longitudinal follow-up',{'case_kind':'clinical_case','species':'human','index_subject_description':p['label'],'care_setting':'paediatric surgical and gastroenterology follow-up'})
  b.fact('demographics',table,'Current follow-up age '+str(age),{'attribute':'age_other','numeric_value':age,'unit':'years','text_value':'current follow-up age'},quote=b.s[table]['text'])
  b.fact('demographics',table,sex,{'attribute':'documented_sex','text_value':sex},quote=f'| {sex} |')
  b.fact('demographics',table,'Age at esophageal replacement '+str(age_surg),{'attribute':'age_other','numeric_value':age_surg,'unit':'years','text_value':'age at esophageal replacement'},quote=b.s[table]['text'])
  return p,ctx
 def followtables(i,age,narr):
  ids=[b.proc('b00005','Venous blood sample collection for hematologic/biochemical testing',quote='a 5ml venous blood sample was collected for hematologic and biochemical analysis.'),b.obs('b00005','Venous sample volume',5,unit='mL',kind='other',quote='a 5ml venous blood sample was collected for hematologic and biochemical analysis.')];sid=f'b{14+i:05}';row=b.s[sid]['text'].split('\n')[-1];cells=[v.strip() for v in row.split('|')]
  for col,name,unit in [(2,'Height','cm'),(3,'Weight','kg'),(4,'Height-for-age Z-score','Z-score'),(5,'Weight-for-age Z-score','Z-score'),(6,'BMI',None)]:
   if cells[col]:ids.append(b.obs(sid,'Current '+name,float(cells[col]),kind='other',**({'unit':unit} if unit else {}),quote=row,time={'text':{1:'At 3 years of age',2:'At 11 years',3:'At 6 years',4:'At 23 years'}[i]},notes='Age is explicit in row and corresponding narrative; no invented calendar date.'))
  for f in b.cur['facts']:
   if f['fact_id'] in ids:f['evidence']+=b.evidence(narr,{1:'At 3 years of age',2:'At 11 years',3:'At 6 years',4:'At 23 years'}[i])
  ids.append(b.obs(sid,'Nutritional classification',kind='other',text_value=cells[7],quote=row))
  labseg=f'b{19+i:05}';row=b.s[labseg]['text'].split('\n')[-1];cells=[v.strip() for v in row.split('|')]
  for col,name,unit in [(1,'Hemoglobin','g/dL'),(2,'Albumin','g/L'),(3,'Ferritin','ng/mL'),(4,'Transferrin','mg/dL'),(5,'Vitamin B12','pg/mL')]:
   flag=('normal' if (i in [3,4] or i==1 and col>1 or i==2 and col>3) else ('low' if i==2 and col<=3 else None))
   ids.append(b.obs(labseg,'Current '+name,float(cells[col]),unit=unit,quote=row,**({'flag':flag} if flag else {}),extra_notes='') if False else b.fact('observations',labseg,'Current '+name+': '+cells[col],{'name':'Current '+name,'kind':'laboratory','status':'resulted','numeric_value':float(cells[col]),'unit':unit,**({'flag':flag} if flag else {})},quote=row,extra_ev=b.evidence(narr),notes='Flag comes from patient-specific narrative; reference limits are not numerically supplied. Hemoglobin borderline low for P2.'))
  qsid=f'b{23+i:05}';row=b.s[qsid]['text'].split('\n')[-1];cells=[v.strip() for v in row.split('|')]
  for col,name in [(2,'Physical'),(3,'Emotional'),(4,'Social'),(5,'School/work' if i==4 else 'School'),(6,'Total')]:ids.append(b.obs(qsid,'Current PedsQL '+name,float(cells[col]),kind='other',unit='score',quote=row,notes='PedsQL scored on 0–100 scale by article methods; no baseline change inferred.'))
  return ids
