def adenoma_bariatric_cases():
 b=Builder('PMC12881035.1')
 for label,sid,tab,age,op,pre,post,ewl,interval in [('Patient A: 37-year-old woman with three hepatic adenomas','b00022','b00019',37,'Roux-en-Y gastric bypass',46.92,29.87,77.8,36),('Patient B: 42-year-old woman with segment II hepatic adenoma','b00023','b00020',42,'Roux-en-Y gastric bypass',38.03,23.73,109.0,48),('Patient C: 35-year-old woman with segment IVb hepatic adenoma','b00024','b00021',35,'Sleeve gastrectomy',40.76,36.20,28.9,7.5)]:
  p=b.patient(label,sid);pid=p['patient_id']
  ctx=b.fact('case_context',sid,label,{'case_kind':'clinical_case','species':'human','index_subject_description':label,'care_setting':'quaternary academic medical center bariatric surgery series'},quote=b.s[sid]['text'],extra_ev=b.evidence('b00010','This is a retrospective case series of adult patients from a single, quaternary academic medical center'))
  ag=b.fact('demographics',sid,'Age at bariatric surgery '+str(age),{'attribute':'age_other','numeric_value':age,'unit':'years'},quote=str(age)+'-year-old female',notes='Narrative describes age in the bariatric surgery case; not reassigned to earlier diagnostic imaging.')
  sex=b.fact('demographics',sid,'Female',{'attribute':'documented_sex','text_value':'female'},quote='female')
  base=b.obs(tab,'Preoperative BMI',pre,unit='kg/m^2',kind='other',time={'text':'Pre-op BMI','relation':'before','anchor':'bariatric surgery'},quote=b.s[tab]['text'])
  after=b.obs(tab,'Postoperative BMI',post,unit='kg/m^2',kind='other',time={'text':'Post-op BMI','relation':'after','anchor':'bariatric surgery'},quote=b.s[tab]['text'])
  ewlid=b.obs(tab,'Excess weight loss',ewl,unit='%',kind='other',text_value=str(ewl)+'%',quote=b.s[tab]['text'],notes='Reported percent excess weight loss, not total-body-weight loss. No recomputation or correction; 109% is retained for Patient B.' if pid=='p2' else 'Reported excess-weight-loss percentage, not total body-weight loss.')
